// AUTO-GENERATED baseline snapshot of real-world regex pattern trees.
// Generated from dotnet/runtime-assets Regex_RealWorldPatterns.json
// Total patterns: 18931 (skipped 0 with problematic chars)
// Purpose: Detect accidental deoptimizations when modifying regex optimization passes.
//
// Expected trees are loaded from real_world_expected_trees.json (generated by
// RegexBaselineGenerator.GenerateJsonBaseline). Workflow:
//   1. Run GenerateJsonBaseline to snapshot current optimizer output
//   2. Make optimizer changes
//   3. Run RealWorldPatternTreeBaseline — any pattern whose tree changed will fail
//   4. Re-run GenerateJsonBaseline to accept the new baseline

using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Text.Json;
using Xunit;

namespace System.Text.RegularExpressions.Tests
{
    public class RegexReductionBaselineTests
    {
        private static Dictionary<string, string> s_expectedTrees;

        /// <summary>
        /// Loads expected trees from real_world_expected_trees.json if it exists.
        /// Key is "pattern\toptions", value is flattened tree string.
        /// </summary>
        private static Dictionary<string, string> GetExpectedTrees()
        {
            if (s_expectedTrees != null) return s_expectedTrees;

            s_expectedTrees = new Dictionary<string, string>();
            string jsonPath = Path.Combine(Path.GetDirectoryName(typeof(RegexReductionBaselineTests).Assembly.Location), "real_world_expected_trees.json");
            if (!File.Exists(jsonPath)) return s_expectedTrees;

            using JsonDocument doc = JsonDocument.Parse(File.ReadAllText(jsonPath));
            foreach (JsonElement entry in doc.RootElement.EnumerateArray())
            {
                string p = entry.GetProperty("p").GetString();
                int o = entry.GetProperty("o").GetInt32();
                string key = $"{p}\t{o}";
                if (entry.TryGetProperty("t", out JsonElement treeEl))
                    s_expectedTrees[key] = treeEl.GetString();
            }
            return s_expectedTrees;
        }

        /// <summary>
        /// Flattens a multi-line tree ToString() to a single line for comparison.
        /// </summary>
        private static string FlattenTree(string tree)
        {
            var sb = new System.Text.StringBuilder();
            bool first = true;
            foreach (string rawLine in tree.Split('\n'))
            {
                string line = rawLine.TrimEnd('\r');
                if (!first) sb.Append('|');
                sb.Append(line);
                first = false;
            }
            return sb.ToString();
        }

        /// <summary>
        /// Parses each real-world pattern through the full optimization pipeline
        /// and verifies the resulting flattened tree matches the expected baseline
        /// from real_world_expected_trees.json.
        /// </summary>
        [Theory]
        [MemberData(nameof(RealWorldPatterns))]
        public void RealWorldPatternTreeBaseline(string pattern, int options)
        {
            var expectedTrees = GetExpectedTrees();
            string key = $"{pattern}\t{options}";
            expectedTrees.TryGetValue(key, out string expectedTree);

            try
            {
                string actual = FlattenTree(RegexParser.Parse(pattern, (RegexOptions)options, CultureInfo.InvariantCulture).Root.ToString());
                if (expectedTree != null)
                {
                    Assert.Equal(expectedTree, actual);
                }
            }
            catch (RegexParseException)
            {
                if (expectedTree != null)
                {
                    Assert.Fail($"Pattern was expected to parse but got RegexParseException");
                }
            }
        }

